"""
Dependencies API Router
"""
from typing import List, Optional
from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from app.db import get_db
from app.db.models import Dependency, EcosystemType, Project
from app.schemas import DependencyCreate, DependencyOut

router = APIRouter(prefix="/projects/{project_id}/dependencies", tags=["Dependencies"])


def _get_project(project_id: int, db: Session) -> Project:
    p = db.query(Project).filter(Project.id == project_id).first()
    if not p:
        raise HTTPException(status_code=404, detail=f"Project {project_id} not found")
    return p


@router.get("/", response_model=List[DependencyOut])
def list_dependencies(
    project_id: int,
    is_direct: Optional[bool] = None,
    is_dev: Optional[bool] = None,
    ecosystem: Optional[str] = None,
    skip: int = 0,
    limit: int = 200,
    db: Session = Depends(get_db),
):
    _get_project(project_id, db)
    q = db.query(Dependency).filter(Dependency.project_id == project_id)
    if is_direct is not None:
        q = q.filter(Dependency.is_direct == is_direct)
    if is_dev is not None:
        q = q.filter(Dependency.is_dev == is_dev)
    if ecosystem:
        q = q.filter(Dependency.ecosystem == ecosystem)
    return q.offset(skip).limit(limit).all()


@router.post("/", response_model=DependencyOut, status_code=status.HTTP_201_CREATED)
def add_dependency(
    project_id: int, payload: DependencyCreate, db: Session = Depends(get_db)
):
    _get_project(project_id, db)
    dep = Dependency(project_id=project_id, **payload.model_dump())
    db.add(dep)
    db.commit()
    db.refresh(dep)
    return dep


@router.post("/bulk", response_model=List[DependencyOut], status_code=status.HTTP_201_CREATED)
def bulk_add_dependencies(
    project_id: int,
    payload: List[DependencyCreate],
    db: Session = Depends(get_db),
):
    """Add multiple dependencies at once (replaces existing list)."""
    _get_project(project_id, db)
    # Clear existing
    db.query(Dependency).filter(Dependency.project_id == project_id).delete()
    deps = [Dependency(project_id=project_id, **d.model_dump()) for d in payload]
    db.add_all(deps)
    db.commit()
    for d in deps:
        db.refresh(d)
    return deps


@router.get("/{dep_id}", response_model=DependencyOut)
def get_dependency(project_id: int, dep_id: int, db: Session = Depends(get_db)):
    dep = _get_dep(project_id, dep_id, db)
    return dep


@router.delete("/{dep_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_dependency(project_id: int, dep_id: int, db: Session = Depends(get_db)):
    dep = _get_dep(project_id, dep_id, db)
    db.delete(dep)
    db.commit()


def _get_dep(project_id: int, dep_id: int, db: Session) -> Dependency:
    dep = db.query(Dependency).filter(
        Dependency.project_id == project_id, Dependency.id == dep_id
    ).first()
    if not dep:
        raise HTTPException(status_code=404, detail=f"Dependency {dep_id} not found")
    return dep

"""
Scans & Findings API Router
"""
from datetime import datetime
from typing import List, Optional
from fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, status
from sqlalchemy.orm import Session

from app.db import get_db
from app.db.models import (
    Project, SecurityScan, ScanStatus, VulnerabilityFinding,
    Remediation, RemediationStatus
)
from app.schemas import (
    ScanCreate, ScanOut, FindingOut,
    RemediationCreate, RemediationUpdate, RemediationOut, RiskReport
)
from app.core.scanner import SecurityScanner

router = APIRouter(tags=["Scans & Findings"])


# ──────────────────────────────────────────────
# Scans
# ──────────────────────────────────────────────

@router.get("/projects/{project_id}/scans", response_model=List[ScanOut])
def list_scans(
    project_id: int,
    skip: int = 0,
    limit: int = 20,
    db: Session = Depends(get_db),
):
    _get_project(project_id, db)
    return (
        db.query(SecurityScan)
        .filter(SecurityScan.project_id == project_id)
        .order_by(SecurityScan.id.desc())
        .offset(skip)
        .limit(limit)
        .all()
    )


@router.post(
    "/projects/{project_id}/scans",
    response_model=ScanOut,
    status_code=status.HTTP_201_CREATED,
)
def trigger_scan(
    project_id: int,
    payload: ScanCreate,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
):
    _get_project(project_id, db)
    scan = SecurityScan(
        project_id=project_id,
        scan_type=payload.scan_type,
        triggered_by=payload.triggered_by,
        status=ScanStatus.PENDING,
    )
    db.add(scan)
    db.commit()
    db.refresh(scan)

    # Run in background so the API returns immediately
    background_tasks.add_task(_run_scan_bg, scan.id)
    return scan


@router.get("/projects/{project_id}/scans/{scan_id}", response_model=ScanOut)
def get_scan(project_id: int, scan_id: int, db: Session = Depends(get_db)):
    return _get_scan(project_id, scan_id, db)


# ──────────────────────────────────────────────
# Findings
# ──────────────────────────────────────────────

@router.get("/projects/{project_id}/scans/{scan_id}/findings", response_model=List[FindingOut])
def list_findings(
    project_id: int,
    scan_id: int,
    severity: Optional[str] = None,
    threat_type: Optional[str] = None,
    skip: int = 0,
    limit: int = 100,
    db: Session = Depends(get_db),
):
    _get_scan(project_id, scan_id, db)
    q = db.query(VulnerabilityFinding).filter(VulnerabilityFinding.scan_id == scan_id)
    if severity:
        q = q.filter(VulnerabilityFinding.severity == severity)
    if threat_type:
        q = q.filter(VulnerabilityFinding.threat_type == threat_type)
    return q.offset(skip).limit(limit).all()


@router.get("/findings/{finding_id}", response_model=FindingOut)
def get_finding(finding_id: int, db: Session = Depends(get_db)):
    f = db.query(VulnerabilityFinding).filter(VulnerabilityFinding.id == finding_id).first()
    if not f:
        raise HTTPException(status_code=404, detail=f"Finding {finding_id} not found")
    return f


# ──────────────────────────────────────────────
# Remediations
# ──────────────────────────────────────────────

@router.get("/findings/{finding_id}/remediations", response_model=List[RemediationOut])
def list_remediations(finding_id: int, db: Session = Depends(get_db)):
    return db.query(Remediation).filter(Remediation.finding_id == finding_id).all()


@router.post(
    "/findings/{finding_id}/remediations",
    response_model=RemediationOut,
    status_code=status.HTTP_201_CREATED,
)
def create_remediation(
    finding_id: int, payload: RemediationCreate, db: Session = Depends(get_db)
):
    f = db.query(VulnerabilityFinding).filter(VulnerabilityFinding.id == finding_id).first()
    if not f:
        raise HTTPException(status_code=404, detail=f"Finding {finding_id} not found")
    rem = Remediation(finding_id=finding_id, **payload.model_dump())
    db.add(rem)
    db.commit()
    db.refresh(rem)
    return rem


@router.patch("/remediations/{rem_id}", response_model=RemediationOut)
def update_remediation(
    rem_id: int, payload: RemediationUpdate, db: Session = Depends(get_db)
):
    rem = db.query(Remediation).filter(Remediation.id == rem_id).first()
    if not rem:
        raise HTTPException(status_code=404, detail=f"Remediation {rem_id} not found")
    for field, value in payload.model_dump(exclude_none=True).items():
        setattr(rem, field, value)
    if payload.status in (RemediationStatus.RESOLVED, RemediationStatus.WONT_FIX,
                          RemediationStatus.FALSE_POSITIVE):
        rem.resolved_at = datetime.utcnow()
    db.commit()
    db.refresh(rem)
    return rem


# ──────────────────────────────────────────────
# Risk Report
# ──────────────────────────────────────────────

@router.get("/projects/{project_id}/report", response_model=RiskReport)
def get_risk_report(project_id: int, db: Session = Depends(get_db)):
    project = _get_project(project_id, db)
    last_scan = (
        db.query(SecurityScan)
        .filter(SecurityScan.project_id == project_id)
        .order_by(SecurityScan.id.desc())
        .first()
    )
    if not last_scan:
        raise HTTPException(
            status_code=404,
            detail="No scans found for this project. Run a scan first."
        )

    findings = (
        db.query(VulnerabilityFinding)
        .filter(VulnerabilityFinding.scan_id == last_scan.id)
        .order_by(VulnerabilityFinding.severity)
        .all()
    )

    from app.db.models import Dependency, RemediationStatus as RS
    deps = db.query(Dependency).filter(Dependency.project_id == project_id).all()
    direct = sum(1 for d in deps if d.is_direct)
    transitive = len(deps) - direct

    threat_breakdown = {}
    for f in findings:
        key = f.threat_type.value
        threat_breakdown[key] = threat_breakdown.get(key, 0) + 1

    rem_all = (
        db.query(Remediation)
        .join(VulnerabilityFinding)
        .filter(VulnerabilityFinding.scan_id == last_scan.id)
        .all()
    )
    rem_summary = {s.value: 0 for s in RS}
    for r in rem_all:
        rem_summary[r.status.value] = rem_summary.get(r.status.value, 0) + 1

    recommendations = _generate_recommendations(findings, deps)

    return RiskReport(
        project_id=project_id,
        project_name=project.name,
        generated_at=datetime.utcnow(),
        risk_score=last_scan.risk_score,
        total_dependencies=len(deps),
        direct_dependencies=direct,
        transitive_dependencies=transitive,
        total_findings=len(findings),
        critical_count=last_scan.critical_count,
        high_count=last_scan.high_count,
        medium_count=last_scan.medium_count,
        low_count=last_scan.low_count,
        threat_breakdown=threat_breakdown,
        top_findings=[FindingOut.model_validate(f) for f in findings[:10]],
        remediation_summary=rem_summary,
        sbom=last_scan.sbom,
        recommendations=recommendations,
    )


# ──────────────────────────────────────────────
# Helpers
# ──────────────────────────────────────────────

def _get_project(project_id: int, db: Session):
    p = db.query(Project).filter(Project.id == project_id).first()
    if not p:
        raise HTTPException(status_code=404, detail=f"Project {project_id} not found")
    return p


def _get_scan(project_id: int, scan_id: int, db: Session) -> SecurityScan:
    scan = db.query(SecurityScan).filter(
        SecurityScan.id == scan_id,
        SecurityScan.project_id == project_id,
    ).first()
    if not scan:
        raise HTTPException(status_code=404, detail=f"Scan {scan_id} not found")
    return scan


def _run_scan_bg(scan_id: int):
    """Background task — gets its own DB session."""
    from app.db.database import SessionLocal
    db = SessionLocal()
    try:
        scan = db.query(SecurityScan).filter(SecurityScan.id == scan_id).first()
        if scan:
            scanner = SecurityScanner(db)
            scanner.run_scan(scan)
    finally:
        db.close()


def _generate_recommendations(findings, deps) -> List[str]:
    recs = []
    from app.db.models import ThreatType, SeverityLevel
    types = {f.threat_type for f in findings}

    if ThreatType.DEPENDENCY_CONFUSION in types:
        recs.append(
            "Pin all internal packages to a private registry and use scoped namespaces "
            "(e.g., @company/package-name) to prevent dependency confusion attacks."
        )
    if ThreatType.MALICIOUS_PACKAGE in types:
        recs.append(
            "Enable hash-pinning (package-lock.json, requirements.txt hashes) and "
            "verify all package signatures before installation."
        )
    if ThreatType.ARTIFACT_TAMPERING in types:
        recs.append(
            "Implement SHA-256 checksums and cryptographic signing for all build artifacts. "
            "Use Sigstore/cosign for keyless artifact signing."
        )
    if ThreatType.BUILD_COMPROMISE in types:
        recs.append(
            "Adopt SLSA level 2+ build provenance. Run builds in ephemeral, hermetic "
            "environments and verify build provenance before deployment."
        )
    if ThreatType.SECRET_LEAKAGE in types:
        recs.append(
            "Immediately rotate all exposed secrets. Use a secrets manager (Vault, AWS Secrets "
            "Manager) and enforce pre-commit secret scanning hooks."
        )
    if ThreatType.SUPPLY_CHAIN_ATTACK in types:
        recs.append(
            "Reduce transitive dependency footprint. Audit and lock the full dependency graph. "
            "Subscribe to security advisories for all direct dependencies."
        )
    if any(f.severity == SeverityLevel.CRITICAL for f in findings):
        recs.insert(0, "⚠️ CRITICAL findings require immediate attention before next deployment.")
    if not deps:
        recs.append("No dependencies recorded. Add your project's dependency manifest.")
    if not recs:
        recs.append("No significant issues detected. Continue monitoring and keep dependencies updated.")
    return recs
